#     an item, and only the owner may change its classification or unit code. Operator commands and migrations run
#     with no user;
#   - an item is never deleted and never moves to another company: it is deactivated, so it stays on every invoice it
#     already appears on;
#   - every insert and every real change of an item writes a history row with the values before and after, in the
#     same statement, so no change can be committed without one;
#   - a history row can be written only by that trigger (not forged by a direct insert), and is never updated or deleted.
# Messages never contain a row value.

ITEM_GUARD_FUNCTION = """
CREATE FUNCTION item_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS
$$
DECLARE
    v_role text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'an item cannot be deleted; deactivate it instead';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.company_id <> OLD.company_id THEN
        RAISE EXCEPTION 'an item cannot move to another company';
    END IF;
    IF app_user_id() IS NOT NULL THEN
        SELECT role INTO v_role FROM core_companyaccess
        WHERE user_id = app_user_id() AND company_id = NEW.company_id;
        IF v_role IS NULL OR v_role NOT IN ('owner', 'staff') THEN
            RAISE EXCEPTION 'only the owner and staff of the company may change its items' USING ERRCODE = '42501';
        END IF;
        IF TG_OP = 'UPDATE' AND v_role <> 'owner'
           AND (NEW.classification_code, NEW.unit_code) IS DISTINCT FROM (OLD.classification_code, OLD.unit_code) THEN
            RAISE EXCEPTION 'only the owner of the company may change the LHDN codes of an item' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END
$$
"""

ITEM_RECORD_FUNCTION = """
CREATE FUNCTION item_record_change() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS
$$
DECLARE
    v_before jsonb;
    v_after jsonb;
    v_email text;
BEGIN
    v_after := jsonb_build_object(
        'name', NEW.name, 'classification_code', NEW.classification_code, 'unit_code', NEW.unit_code,
        'default_tax_type', NEW.default_tax_type, 'is_active', NEW.is_active);
    IF TG_OP = 'UPDATE' THEN
        v_before := jsonb_build_object(
            'name', OLD.name, 'classification_code', OLD.classification_code, 'unit_code', OLD.unit_code,
            'default_tax_type', OLD.default_tax_type, 'is_active', OLD.is_active);
        IF v_before = v_after THEN
            RETURN NULL;
        END IF;
    END IF;
    -- The signed-in user can read their own user row, so their address is copied here: a colleague who later reads
    -- the history cannot read that row. An operator command has no user and leaves it empty.
    SELECT email INTO v_email FROM core_user WHERE id = app_user_id();
    INSERT INTO core_itemchange (company_id, item_id, changed_by_id, changed_by_email, changed_at, before, after)
    VALUES (NEW.company_id, NEW.id, app_user_id(), coalesce(v_email, ''), now(), v_before, v_after);
    RETURN NULL;
END
$$
"""

CHANGE_GUARD_FUNCTION = """
CREATE FUNCTION item_change_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS
$$
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'the item history cannot be changed or deleted';
    END IF;
    -- Depth 1 is this statement's own trigger; the history trigger of core_item runs one level above it.
    IF pg_trigger_depth() < 2 THEN
        RAISE EXCEPTION 'the item history is written only when an item changes';
    END IF;
    RETURN NEW;
END
$$
"""

